<script setup lang="ts">
import { useRoute,useRouter } from 'vue-router'
import { useMemberStore } from '../stores/member'
import { usePilotStore } from '../stores/pilot'
import { catalogPhoto,catalogTitle,metroCaption } from '../services/catalog-photos'
import type { CatalogListing } from '../services/catalog-types'
import { money } from '../data/mock'
import AppIcon from './AppIcon.vue'
const props=defineProps<{home:CatalogListing;recordedAt?:string;variant?:'row'|'hero'}>()
const member=useMemberStore(),pilot=usePilotStore(),route=useRoute(),router=useRouter()
async function favorite(){if(!member.loggedIn){void router.push({path:'/account',query:{redirect:route.fullPath}});return}try{await member.toggleFavorite(props.home.id)}catch(error){pilot.notify(error instanceof Error?error.message:'收藏暂时失败，请重试')}}
function fallback(event:Event){const image=event.target as HTMLImageElement;if(!image.src.endsWith('/placeholder.svg'))image.src='/assets/catalog/placeholder.svg'}
</script>
<template><article :class="['rental-card', 'variant-' + (variant || 'row')]"><RouterLink :to="`/listing/${home.id}`" class="rental-card-link" data-testid="catalog-card" :data-id="home.id" :aria-label="`查看${catalogTitle(home)} ${money(home.rent)}每月`"><span class="rental-card-photo"><img :src="catalogPhoto(home)" :alt="`${catalogTitle(home)}室内示意，非该房源实拍`" loading="lazy" width="240" height="300" @error="fallback"/><span>示意图</span></span><span class="rental-card-copy"><strong>{{ catalogTitle(home) }}</strong><span>{{ home.area }}㎡ · {{ home.rentalType==='SHARED'?'合租单间':home.layout }}</span><span>{{ home.district }} · {{ home.town }}</span><span>{{ metroCaption(home) }}</span><b>{{ money(home.rent) }}<small>/月</small></b><small v-if="recordedAt" class="recorded-date">{{ new Date(recordedAt).toLocaleDateString('zh-CN') }}</small></span></RouterLink><button class="icon-button rental-card-save" :aria-label="(member.favoriteIds.includes(home.id)?'取消收藏':'收藏')+catalogTitle(home)" :aria-pressed="member.favoriteIds.includes(home.id)" :disabled="member.loggedIn&&(!member.favoritesReady||member.busyIds.has(home.id))" @click="favorite"><AppIcon name="heart" :size="18" :fill="member.favoriteIds.includes(home.id)?'currentColor':'none'"/></button></article></template>
<style scoped>
.rental-card{position:relative;border-bottom:1px solid var(--line)}.rental-card-link{display:grid;grid-template-columns:34% minmax(0,1fr);gap:15px;width:100%;text-align:left;padding:20px 0}.rental-card-photo{display:block;position:relative;align-self:start;border-radius:13px;overflow:hidden;aspect-ratio:4/5;background:var(--surface)}.rental-card-photo img{display:block;width:100%;height:100%;object-fit:cover}.rental-card-photo>span{position:absolute;left:7px;bottom:7px;padding:3px 6px;background:#fff;border-radius:4px;font-size:11px;color:#555}.rental-card-copy{display:flex;flex-direction:column;gap:5px;min-width:0}.rental-card-copy>strong{font-size:15px;font-weight:600;line-height:1.6;margin-bottom:3px}.rental-card-copy>span{font-size:13px;color:var(--muted);line-height:1.65;overflow-wrap:anywhere}.rental-card-copy>b{font-size:23px;font-weight:600;letter-spacing:-.035em;margin-top:auto;padding-top:9px;line-height:1.3}.rental-card-copy>b small{font-size:12px;font-weight:400;color:var(--muted);margin-left:5px;letter-spacing:0}.rental-card-save{position:absolute;top:26px;left:calc(34% - 50px);background:#fff;min-width:44px;min-height:44px;width:44px;border-radius:50%}.recorded-date{font-size:11px;color:var(--muted)}@media(max-width:359px){.rental-card-link{gap:12px}.rental-card-copy>strong{font-size:14px}.rental-card-copy>b{font-size:21px}}
.variant-hero .rental-card{border-bottom:0;margin-bottom:22px}.variant-hero .rental-card-link{grid-template-columns:1fr;gap:0;padding:0}.variant-hero .rental-card-photo{aspect-ratio:16/10;border-radius:24px}.variant-hero .rental-card-copy{padding:15px 2px 2px;gap:4px}.variant-hero .rental-card-copy>strong{font-size:20px;font-weight:650;line-height:1.4;margin-bottom:2px}.variant-hero .rental-card-copy>span{font-size:12px}.variant-hero .rental-card-copy>b{font-size:28px;font-weight:600;padding:14px 54px 0 0;position:relative;letter-spacing:-.05em}.variant-hero .rental-card-copy>b::after{content:'→';position:absolute;right:0;bottom:0;width:42px;height:42px;display:grid;place-items:center;border-radius:50%;background:var(--ink);color:#fff;font-size:17px;letter-spacing:0}.variant-hero .rental-card-save{top:14px;left:auto;right:14px;background:rgba(255,255,255,.94)}
</style>
